<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {beforeNavigate,goto} from '$app/navigation';
 import {page} from '$app/stores';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 import type {PublishingGateway,StudioProject,ChapterChoice,Revision} from '../application/publishing';
 import type {TitleChangesGateway,TitleChange} from '$lib/features/catalog/application/title-changes';
 import {canEdit} from '../domain/revision';
 import {projectListReturn} from '../domain/workspace-context';
 import {publicationStates} from './messages';
 import ProjectNavigation from './ProjectNavigation.svelte';
 import ProjectCover from './ProjectCover.svelte';
 let {projectId,gateway,changes}:{projectId:string;gateway:PublishingGateway;changes:TitleChangesGateway}=$props();
 const {locale}=useLocale();const names=$derived(publicationStates($locale));
 const section=$derived(['chapters','requests'].includes($page.url.searchParams.get('section')||'')?$page.url.searchParams.get('section')!:'overview');
 const returnTo=$derived(projectListReturn($page.url.searchParams.get('projectsReturn')));
 let project=$state<StudioProject|null>(null),chapters=$state<ChapterChoice[]>([]),revisions=$state<Revision[]>([]),requests=$state<TitleChange[]>([]);
 let loading=$state(true),busy=$state(false),error=$state(''),requestError=$state(''),requestsLoading=$state(false),moreChapters=$state(false),moreRevisions=$state(false),moreRequests=$state(false);
 let dialog=$state<HTMLDialogElement>(),trigger=$state<HTMLButtonElement>(),label=$state(''),volume=$state(''),name=$state(''),order=$state<number|undefined>(),createdChapter=$state('');
 let alive=true,requestGeneration=0,loadGeneration=0;
 const editor=$derived(project?.approved&&project.status==='active'&&['owner','editor'].includes(project.role));
 const draft=$derived(revisions.find(item=>canEdit(item.state)));
 const dirty=$derived(!!(label||volume||name||order||createdChapter));
 function editorHref(id:string){return '/studio/projects/'+encodeURIComponent(projectId)+'?revision='+encodeURIComponent(id)+'&projectsReturn='+encodeURIComponent(returnTo);}
 async function load(){const generation=++loadGeneration;loading=true;error='';try{const [p,c,r]=await Promise.all([gateway.project(projectId),gateway.chapters(projectId),gateway.revisions(projectId)]);if(!alive||generation!==loadGeneration)return;project=p;chapters=c;revisions=r;moreChapters=c.length===100;moreRevisions=r.length===100;}catch(e){if(alive&&generation===loadGeneration)error=failureCode(e);}finally{if(alive&&generation===loadGeneration)loading=false;}}
 async function loadRequests(more=false){const generation=++requestGeneration;requestsLoading=true;requestError='';try{const actor=await changes.currentAccount();if(!actor)throw Error('unauthorized');const result=await changes.list(actor,projectId,more?requests.at(-1)?.id:undefined);if(!alive||generation!==requestGeneration)return;requests=more?[...requests,...result.items]:result.items;moreRequests=result.has_more;}catch(e){if(alive&&generation===requestGeneration)requestError=failureCode(e);}finally{if(alive&&generation===requestGeneration)requestsLoading=false;}}
 onMount(()=>{void load();void loadRequests();const stop=changes.watchAccount(()=>{requests=[];project=null;chapters=[];revisions=[];requestGeneration++;label='';volume='';name='';order=undefined;createdChapter='';dialog?.close();void load();void loadRequests();});const warn=(event:BeforeUnloadEvent)=>{if(dirty||busy){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',warn);return()=>{alive=false;loadGeneration++;requestGeneration++;stop();window.removeEventListener('beforeunload',warn);};});
 async function showCreate(){error='';await tick();dialog?.showModal();dialog?.querySelector('input')?.focus();}
 async function closeCreate(){if(busy)return;if(dirty&&!window.confirm(text($locale,'Тарау деректерін өшіру керек пе?','Сбросить данные новой главы?')))return;label='';volume='';name='';order=undefined;createdChapter='';dialog?.close();await tick();trigger?.focus();}
 async function create(){if(busy||!editor)return;busy=true;error='';try{if(!createdChapter)createdChapter=await gateway.createChapter(projectId,{label,volume,name,order:order||0});const revision=await gateway.create(projectId,createdChapter);if(!alive)return;label='';volume='';name='';order=undefined;createdChapter='';dialog?.close();busy=false;await goto(editorHref(revision.id));}catch(e){if(alive)error=failureCode(e);}finally{if(alive)busy=false;}}
 async function more(kind:'chapters'|'revisions'){busy=true;error='';try{if(kind==='chapters'){const next=await gateway.chapters(projectId,chapters.length);if(alive){chapters=[...chapters,...next];moreChapters=next.length===100;}}else{const next=await gateway.revisions(projectId,revisions.length);if(alive){revisions=[...revisions,...next];moreRevisions=next.length===100;}}}catch(e){if(alive)error=failureCode(e);}finally{if(alive)busy=false;}}
 async function openChapter(id:string){busy=true;error='';try{const revision=await gateway.create(projectId,id);if(alive){busy=false;await goto(editorHref(revision.id));}}catch(e){if(alive)error=failureCode(e);}finally{if(alive)busy=false;}}
 beforeNavigate(navigation=>{if(busy||(dirty&&!window.confirm(text($locale,'Сақталмаған деректер бар. Шығу керек пе?','Есть несохранённые данные. Уйти?'))))navigation.cancel();});
</script>
<svelte:head><title>{project?.titleName||text($locale,'Жоба','Проект')} — Qmanga Studio</title></svelte:head>
<a class="back-link" href={returnTo}>← {text($locale,'Барлық жобалар','Все проекты')}</a>
<header class="project-heading"><div class="identity">{#if project}<ProjectCover name={project.titleName} url={project.coverId?'/api/v1/media/'+encodeURIComponent(project.coverId):undefined}/>{/if}<div><h1>{project?.titleName||text($locale,'Жоба','Проект')}</h1>{#if project}<p>{project.teamName}</p>{/if}</div></div>{#if editor}<button bind:this={trigger} class="button primary" onclick={showCreate} disabled={busy||loading}><span aria-hidden="true">+</span> {text($locale,'Тарау қосу','Добавить главу')}</button>{/if}</header>
<ProjectNavigation {projectId} current={section} {returnTo}/>
{#if loading}<p role="status">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}
{#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{#if !project}<button class="button subtle" onclick={load}>{text($locale,'Қайталау','Повторить')}</button>{/if}{/if}
{#if project&&!loading}
{#if section==='requests'}
 <section><h2>{text($locale,'Өзгерту өтінімдері','Заявки на правки')}</h2>{#if requestError}<p role="alert">{noticeText($locale,requestError)}</p><button class="button subtle" onclick={()=>loadRequests()}>{text($locale,'Қайталау','Повторить')}</button>{/if}{#if requestsLoading}<p role="status">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}<div class="chapter-list">{#each requests as item}<article class="chapter-row"><div><h3><a href={'/studio/title-changes/'+encodeURIComponent(item.id)}>{item.reason}</a></h3><p>{new Date(item.created_at).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')}</p></div><span class="state">{item.status==='pending'?text($locale,'Қаралуда','На рассмотрении'):item.status==='approved'?text($locale,'Мақұлданды','Одобрено'):text($locale,'Қайтарылды','Возвращено')}</span></article>{:else}{#if !requestsLoading&&!requestError}<p class="empty">{text($locale,'Өтінімдер әлі жоқ.','Заявок пока нет.')}</p>{/if}{/each}</div>{#if moreRequests}<button class="button subtle" disabled={requestsLoading} onclick={()=>loadRequests(true)}>{text($locale,'Тағы жүктеу','Загрузить ещё')}</button>{/if}</section>
{:else}
 <div class="project-body"><section>
 {#if section==='overview'&&draft}<div class="continue-draft"><div><h2>{text($locale,'Нобайды жалғастыру','Продолжить черновик')}</h2><p>{text($locale,draft.chapterLabel+'-тарау','Глава '+draft.chapterLabel)} · {names[draft.state]}</p></div><a class="button subtle" href={editorHref(draft.id)}>{text($locale,'Редакторды ашу','Открыть редактор')} →</a></div>{/if}
 <h2>{text($locale,'Жоба тараулары','Главы проекта')}</h2>
 <div class="chapter-list">{#each chapters as chapter (chapter.id)}{@const versions=revisions.filter(item=>item.chapterId===chapter.id)}<article class="chapter-entry"><div class="chapter-title"><h3>{text($locale,chapter.label+'-тарау','Глава '+chapter.label)}{#if chapter.name} · {chapter.name}{/if}</h3>{#if !versions.length}<button class="button subtle" disabled={busy||!project.approved||project.status!=='active'} onclick={()=>openChapter(chapter.id)}>{text($locale,'Нобай ашу','Открыть черновик')}</button>{/if}</div>{#each versions as revision}<div class="version-row"><span class="state">{names[revision.state]||revision.state}</span><a class="button subtle" href={editorHref(revision.id)}>{canEdit(revision.state)?text($locale,'Өңдеу','Редактировать'):text($locale,'Ашу','Открыть')} →</a></div>{/each}</article>{:else}<p class="empty">{text($locale,'Тараулар әлі жоқ.','Глав пока нет.')}</p>{/each}</div>
 <div class="paging">{#if moreChapters}<button class="button subtle" disabled={busy} onclick={()=>more('chapters')}>{text($locale,'Тағы тараулар','Ещё главы')}</button>{/if}{#if moreRevisions}<button class="button subtle" disabled={busy} onclick={()=>more('revisions')}>{text($locale,'Тағы нұсқалар','Ещё версии')}</button>{/if}</div>
 </section>{#if section==='overview'}<aside class="project-facts"><h2>{text($locale,'Жоба','Проект')}</h2><dl><dt>{text($locale,'Команда','Команда')}</dt><dd>{project.teamName}</dd><dt>{text($locale,'Менің рөлім','Моя роль')}</dt><dd>{project.role==='owner'?text($locale,'Иесі','Владелец'):project.role==='editor'?text($locale,'Редактор','Редактор'):text($locale,'Қатысушы','Участник')}</dd><dt>{text($locale,'Күйі','Состояние')}</dt><dd>{project.approved&&project.status==='active'?text($locale,'Белсенді','Активен'):text($locale,'Белсенді емес','Неактивен')}</dd></dl><a class="button subtle" href={'/studio/projects/'+encodeURIComponent(projectId)+'/metadata?projectsReturn='+encodeURIComponent(returnTo)}>{text($locale,'Тайтл туралы','Сведения о тайтле')}</a></aside>{/if}</div>
{/if}
{/if}
<dialog bind:this={dialog} class="new-chapter-dialog" aria-labelledby="new-chapter-title" oncancel={event=>{event.preventDefault();void closeCreate();}}><div class="dialog-heading"><h2 id="new-chapter-title">{text($locale,'Тарау қосу','Добавить главу')}</h2><button type="button" class="button subtle" aria-label={text($locale,'Жабу','Закрыть')} disabled={busy} onclick={closeCreate}>×</button></div><p class="muted">{text($locale,'Команданың нобайы. Оқырмандарға әлі көрінбейді.','Черновик команды. Читатели пока его не видят.')}</p>{#if error}<p role="alert">{noticeText($locale,error)}</p>{/if}<form onsubmit={event=>{event.preventDefault();void create();}}><fieldset disabled={busy||!!createdChapter}><label>{text($locale,'Тарау нөмірі немесе атауы','Номер или обозначение главы')}<input bind:value={label} required maxlength="64" placeholder="12, 12.5, Special"/></label><div class="chapter-fields"><label>{text($locale,'Том · міндетті емес','Том · необязательно')}<input bind:value={volume} maxlength="32"/></label><label>{text($locale,'Атауы · міндетті емес','Название · необязательно')}<input bind:value={name} maxlength="200"/></label></div><details><summary>{text($locale,'Тізімдегі реті','Порядок в списке')}</summary><label>{text($locale,'Бос қалса — соңына қосылады','Пусто — добавить в конец')}<input bind:value={order} type="number" min="1" max="1000000"/></label></details></fieldset>{#if createdChapter}<p role="status">{text($locale,'Тарау жасалды. Нобайды ашуды қайтала.','Глава создана. Повтори открытие черновика.')}</p>{/if}<div class="dialog-actions"><button type="button" class="button subtle" disabled={busy} onclick={closeCreate}>{text($locale,'Бас тарту','Отмена')}</button><button class="button primary" disabled={busy}>{busy?text($locale,'Жасалуда…','Создание…'):createdChapter?text($locale,'Нобай ашу','Открыть черновик'):text($locale,'Нобай жасау','Создать черновик')}</button></div></form></dialog>
<style>
 .back-link{display:inline-flex;align-items:center;min-height:44px;font-size:13px;color:var(--muted)}.project-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-top:12px}.identity{display:flex;gap:16px;align-items:center;min-width:0}.identity>div{min-width:0}h1{font-size:24px;line-height:1.3;margin:0;overflow-wrap:anywhere}.identity p{color:var(--muted);font-size:13px}h2{font-size:17px;margin:0 0 14px}h3{font-size:14px;margin:0;overflow-wrap:anywhere}.project-body{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:24px}.project-body>section{min-width:0}.continue-draft{display:flex;align-items:center;justify-content:space-between;gap:14px;background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:18px;margin-bottom:24px}.continue-draft h2{margin:0}.continue-draft p{font-size:13px;color:var(--muted);margin-bottom:0}.chapter-list{border:1px solid var(--line);border-radius:9px;overflow:hidden}.chapter-entry,.chapter-row{padding:14px;border-bottom:1px solid var(--line);min-width:0}.chapter-entry:last-child,.chapter-row:last-child{border:0}.chapter-title,.version-row,.chapter-row{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.version-row{margin-top:6px}.state{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.project-facts{align-self:start;background:var(--panel);padding:18px;border:1px solid var(--line);border-radius:10px;min-width:0}.project-facts dt{font-size:12px;color:var(--muted)}.project-facts dd{font-size:13px;overflow-wrap:anywhere;margin:4px 0 16px}.project-facts a{white-space:normal}.empty{padding:16px;color:var(--muted);font-size:14px}.paging{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}.chapter-row p{font-size:12px;color:var(--muted)}.new-chapter-dialog{width:min(540px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;border:1px solid var(--line);border-radius:12px;padding:24px;color:var(--text);background:var(--panel)}.new-chapter-dialog::backdrop{background:#0009}.dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.dialog-heading h2{font-size:20px;margin:0}.new-chapter-dialog .muted{font-size:13px}.new-chapter-dialog fieldset{border:0;padding:0;min-width:0;display:grid;gap:16px}.new-chapter-dialog label{display:grid;gap:8px;font-size:13px;min-width:0}.new-chapter-dialog input{width:100%;min-width:0}.chapter-fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.new-chapter-dialog summary{display:flex;align-items:center;min-height:44px;font-size:13px}.dialog-actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin-top:20px}
 @media(max-width:799px){.project-body{grid-template-columns:1fr}.continue-draft{align-items:start;flex-direction:column}.project-heading>.button{width:100%}}@media(max-width:479px){.chapter-fields{grid-template-columns:1fr}.new-chapter-dialog{padding:16px}.identity :global(.project-cover){width:52px}h1{font-size:20px}}
</style>
